struct RingBuffer {
    RingBuffer(int capacity) : cap_(capacity), head_(0), count_(0) {}

    bool push(int value) {
        if (full()) return false;
        data_[(head_ + count_) % cap_] = value;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = data_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return true;
    }

    int size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == cap_; }

private:
    static const int kMaxCapacity = 1024;
    int data_[kMaxCapacity];
    int cap_;
    int head_;
    int count_;
};
